() => {
  const out = {};
  out.window = [window.innerWidth, window.innerHeight];
  out.dpr = window.devicePixelRatio;
  const h3s = [...document.querySelectorAll('h3')].map(h => h.textContent);
  out.h3s = h3s;
  const sel = document.querySelector('select');
  out.selectOptions = sel ? [...sel.options].map(o=>o.text) : null;
  const img = document.querySelector('img');
  out.firstImg = img ? {src: img.src.slice(0,60), w: img.getBoundingClientRect().width, h: img.getBoundingClientRect().height} : null;
  return out;
}

