  await page.getByRole('button', { name: /SVG icon/ }).click();
  await page.waitForTimeout(2000);
  const info = await page.evaluate(() => {
    const res = {};
    const app = document.querySelector('#app');
    // find compress root (has grid-area header child)
    const all = document.querySelectorAll('*');
    let compress = null;
    for (const el of all) { const cs = getComputedStyle(el); if (cs.gridTemplateAreas && cs.gridTemplateAreas.includes('viewportOpts')) { compress = el; break; } }
    if (compress) {
      const cs = getComputedStyle(compress);
      res.compress = { areas: cs.gridTemplateAreas, cols: cs.gridTemplateColumns, rows: cs.gridTemplateRows, display: cs.display };
    }
    return res;
  });
  return JSON.stringify(info, null, 1);
}

async (page) => {
  await page.locator('button', { hasText: 'SVG icon' }).first().click();
  await page.waitForTimeout(2500);
  const info = await page.evaluate(() => {
    const res = {};
    for (const el of document.querySelectorAll('*')) {
      const cs = getComputedStyle(el);
      if (cs.gridTemplateAreas && cs.gridTemplateAreas.includes('viewportOpts')) {
        res.compress = { areas: cs.gridTemplateAreas, cols: cs.gridTemplateColumns, rows: cs.gridTemplateRows };
        res.box = el.getBoundingClientRect().toJSON();
        break;
      }
    }
    // find options panel
    return res;
  });
  return JSON.stringify(info, null, 1);
}

