    >
      <path
        className={color === "info" ? "wave-info" : "wave-footer"}
        d={bandPath({
          width: 1920,
          height: 79,
          baseline,
          amplitude,
          cycles: 1,
          phase,
        })}
      />
    </svg>
  );
}

