import { useEffect, useRef, useState } from "react";

export type SnackOptions = {
  /** Optional trailing action label, e.g. "DISMISS". */
  action?: string;
};

type Snack = {
  message: string;
  action?: string;
  key: number;
};

/**
 * Imperative snackbar controller. Mirrors the reference's bottom-centre
 * toast with an optional green action button.
 */
export function useSnackbar(duration = 5000) {
  const [snack, setSnack] = useState<Snack | null>(null);
  const [hiding, setHiding] = useState(false);
  const timer = useRef<number | undefined>(undefined);
  const key = useRef(0);

  const clear = () => {
    if (timer.current) window.clearTimeout(timer.current);
  };

  const dismiss = () => {
    clear();
    setHiding(true);
    timer.current = window.setTimeout(() => {
      setSnack(null);
      setHiding(false);
    }, 300);
  };

  const show = (message: string, _options: SnackOptions = {}) => {
    clear();
    key.current += 1;
    setHiding(false);
    setSnack({ message, key: key.current });
    timer.current = window.setTimeout(dismiss, duration);
  };

  useEffect(() => clear, []);

  const node = snack ? (
    <div
      className={`snackbar${hiding ? " hiding" : ""}`}
      role="status"
      aria-live="polite"
    >
      <div className="snackbar-text">{snack.message}</div>
      <button className="snackbar-action" type="button" onClick={dismiss}>
        Dismiss
      </button>
    </div>
  ) : null;

  return { show, node };
}

import { useCallback, useEffect, useState } from "react";

export const EDITOR_PATH = "/editor";

/** True when the bundle is opened straight from disk rather than a server. */
const fileProtocol =
  typeof window !== "undefined" && window.location.protocol === "file:";

function currentPath(): string {
  if (fileProtocol) {
    // Derive a path from the hash so navigation still works offline.
    const hash = window.location.hash.replace(/^#/, "");
    return hash || "/";
  }
  return window.location.pathname;
}

/**
 * Minimal history-based router. Keeps the real URL paths (`/`, `/editor`)
 * instead of hash routing whenever the page is served over http(s).
 */
export function useRoute() {
  const [path, setPath] = useState<string>(currentPath);

  useEffect(() => {
    const sync = () => setPath(currentPath());
    window.addEventListener("popstate", sync);
    window.addEventListener("hashchange", sync);
    return () => {
      window.removeEventListener("popstate", sync);
      window.removeEventListener("hashchange", sync);
    };
  }, []);

  const navigate = useCallback((next: string) => {
    if (fileProtocol) {
      window.location.hash = next;
      setPath(next);
      return;
    }
    const url = new URL(window.location.href);
    url.pathname = next;
    window.history.pushState(null, "", url.href);
    setPath(next);
  }, []);

  return { path, navigate };
}

