export function IntroPage({ onImage, onNotice }: Props) {
  const inputRef = useRef<HTMLInputElement>(null);
  const [loadingDemo, setLoadingDemo] = useState<string | null>(null);
  const [canInstall, setCanInstall] = useState(false);
  const [dragValid, setDragValid] = useState(false);
  const dragDepth = useRef(0);

  const openFile = useCallback(
    async (file: File | undefined | null) => {
      if (!file) return;
      if (!file.type.startsWith("image/")) {
        onNotice("That doesn't look like an image");
        return;
      }
      const image = await fileToImage(file);
      onImage(image);
    },
    [onImage, onNotice],
  );

  const pickDemo = useCallback(
    async (id: string) => {
      const demo = DEMOS.find((d) => d.id === id);
      if (!demo) return;
      setLoadingDemo(demo.size);
      // Give the badge a beat to render before the editor mounts.
      await new Promise((r) => window.setTimeout(r, 260));
      setLoadingDemo(null);
      onImage(demoToImage(demo));
    },
    [onImage],
  );

  // Clipboard paste support (the "OR Paste" affordance).
  useEffect(() => {
    const onPaste = (event: ClipboardEvent) => {
      const items = event.clipboardData?.items;
      if (!items) return;
      for (const item of items) {
        if (item.type.startsWith("image/")) {
          void openFile(item.getAsFile());
          break;
        }
      }
    };
    document.addEventListener("paste", onPaste);
    return () => document.removeEventListener("paste", onPaste);
  }, [openFile]);

  // Surface the PWA install button only when the browser offers one.
  useEffect(() => {
    const onPrompt = (event: Event) => {
      event.preventDefault();
      setCanInstall(true);
    };
    window.addEventListener("beforeinstallprompt", onPrompt);
    return () => window.removeEventListener("beforeinstallprompt", onPrompt);
  }, []);

  return (
    <div className="abs-fill intro-view">
      <div
        className={`intro-hero${dragValid ? " drag-valid" : ""}`}
        onDragEnter={(e) => {
          e.preventDefault();
          dragDepth.current += 1;
          setDragValid(true);
        }}
        onDragOver={(e) => e.preventDefault()}
        onDragLeave={() => {
          dragDepth.current -= 1;
          if (dragDepth.current <= 0) setDragValid(false);
        }}
        onDrop={(e) => {
          e.preventDefault();
          dragDepth.current = 0;
          setDragValid(false);
          void openFile(e.dataTransfer?.files?.[0]);
        }}
      >
        <input
          ref={inputRef}
          type="file"
          accept="image/*"
          className="visually-hidden"
          onChange={(e) => {
            void openFile(e.target.files?.[0]);
            e.target.value = "";
          }}
        />

        <h1 className="logo-row">
          <img
            className="logo-mark"
            src={logoLockup}
            alt="Squoosh"
            width={539}
            height={162}
          />
        </h1>

        <div className="drop-zone">
          <svg
            className="drop-blob abs-fill"
            viewBox="-1.25 -1.25 2.5 2.5"
            preserveAspectRatio="xMidYMid slice"
            aria-hidden="true"
          >
            {DROP_BLOBS.map((d, i) => (
              <path key={i} d={d} />
            ))}
          </svg>
          <div className="drop-inner">
            <button
              className="drop-icon-btn plain-btn"
              type="button"
              aria-label="Choose an image"
              onClick={() => inputRef.current?.click()}
            >
              <AddImageIcon />
            </button>
            <div className="drop-hint">
              <span className="drop-word">Drop </span>OR{" "}
              <button
                className="paste-link plain-btn"
                type="button"
                onClick={() => inputRef.current?.click()}
              >
                Paste
              </button>
            </div>
          </div>
        </div>
      </div>

      <div className="demos-band">
        <BandWave />
        <div className="demos-pad">
          <p className="demos-heading">
            Or <strong>try one</strong> of these:
          </p>
          <ul className="demo-list">
            {DEMOS.map((demo) => (
              <li key={demo.id}>
                <button
                  className="plain-btn"
                  type="button"
                  aria-label={`${demo.label} ${demo.size}`}
                  onClick={() => void pickDemo(demo.id)}
                >
                  <div className="demo-card">
                    <div className="demo-avatar" style={{ position: "relative" }}>
                      <img src={demo.avatar} alt={demo.label} />
                      {loadingDemo === demo.size && (
                        <div
                          className="abs-fill"
                          style={{
                            background: "rgba(0,0,0,.5)",
                            display: "grid",
                            placeItems: "center",
                          }}
                        >
                          <span
                            className="spinner"
                            style={{ ["--size" as string]: "34px", ["--color" as string]: "#fff" }}
                          />
                        </div>
                      )}
                    </div>
                    <div className="demo-badge">{demo.size}</div>
                  </div>
                </button>
              </li>
            ))}
          </ul>
        </div>
      </div>

      <div className="band-tail">
        <EdgeWave color="info" amplitude={24} baseline={40} phase={0.7} />
      </div>

      {FEATURES.map((feature) => (
        <section className="info-block" key={feature.title}>
          <div className="info-inner">
            <div className="info-grid">
              <div className="info-copy">
                <h2 className="info-heading">{feature.title}</h2>
                <p className="info-body">{feature.body}</p>
              </div>
              <figure className="info-figure">
                <img src={feature.image} alt={feature.alt} />
              </figure>
            </div>
          </div>
        </section>
      ))}

      <footer className="site-footer">
        <div className="footer-band">
          <EdgeWave color="footer" amplitude={22} baseline={42} phase={1.2} />
          <div className="footer-pad">
            <footer className="footer-links">
              <a
                className="footer-link"
                href="https://github.com/GoogleChromeLabs/squoosh/blob/dev/README.md#privacy"
              >
                Privacy
              </a>
              <a
                className="footer-link with-mark"
                href="https://github.com/GoogleChromeLabs/squoosh"
              >
                <img src={githubMark} alt="" width={10} height={10} />
                Source on Github
              </a>
            </footer>
          </div>
        </div>
      </footer>

      {canInstall && (
        <button
          className="install-btn"
          type="button"
          onClick={() => {
            onNotice("Install this page from your browser menu");
            setCanInstall(false);
          }}
        >
          Install
        </button>
      )}
    </div>
  );
}

import { cn } from "@/utils/cn";

type Props = {
  checked: boolean;
  onChange: (next: boolean) => void;
  label: string;
  /** Optional class for the outer wrapper. */
  className?: string;
};

/** Pill switch matching the reference's black track / pink thumb control. */
export function Toggle({ checked, onChange, label, className }: Props) {
  return (
    <span className={cn("switch", className)}>
      <input
        type="checkbox"
        checked={checked}
        aria-label={label}
        onChange={(e) => onChange(e.target.checked)}
      />
      <span className="track">
        <span className="thumb-track">
          <span className="thumb" />
        </span>
      </span>
    </span>
  );
}

import { DownloadIcon } from "@/components/icons";
import { cn } from "@/utils/cn";

type Props = {
  /** Human-readable output size, e.g. "862 kB". */
  size: string;
  /** Percentage of the original size retained, 0-100. */
  ratio: number;
  /** Which side of the compare view this bubble anchors to. */
  side: "a" | "b";
  /** True for the untouched original, which shows a neutral badge. */
  original?: boolean;
  /** Disabled state used while an encode is in flight. */
  busy?: boolean;
  onDownload: () => void;
};

function splitSize(size: string): { amount: string; unit: string } {
  const match = size.match(/^([\d.]+)\s*(.*)$/);
  if (!match) return { amount: size, unit: "" };
  return { amount: match[1], unit: match[2] };
}

const BUBBLE_OUTLINE =
  "url(\"data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='186.5' height='280.3'%3E%3Cpath fill='rgba(30,31,29,0.69)' d='M181.5 0H16.4a5 5 0 00-5 5v134L0 146.5h11.4v128.8a5 5 0 005 5h165.1a5 5 0 005-5V5a5 5 0 00-5-5z'/%3E%3C/svg%3E\")";

export function ResultsBubble({
  size,
  ratio,
  side,
  original = false,
  busy = false,
  onDownload,
}: Props) {
  const { amount, unit } = splitSize(size);
  const direction = original || ratio >= 100 ? "" : "↓";
  const shownPercent = original ? "0" : String(Math.max(0, Math.round(ratio)));

  return (
    <div
      className={cn("results", side === "b" && "side-b-results", original && "is-original")}
    >
      <a
        className={cn("dl-btn", busy && "is-busy")}
        href="#"
        role="button"
        aria-label="Download"
        aria-disabled={busy}
        onClick={(e) => {
          e.preventDefault();
          if (!busy) onDownload();
        }}
      >
        <svg
          className="dl-blob"
          viewBox="-1.25 -1.25 2.5 2.5"
          preserveAspectRatio="xMidYMid slice"
          aria-hidden="true"
        >
          <path d="M1.0083 -0.0115C1.0034 0.2739 0.7441 0.6708 0.5382 0.8371C0.3323 1.0034 0.0071 1.0423 -0.2271 0.9864C-0.4613 0.9305 -0.751 0.7461 -0.867 0.5016C-0.9831 0.2571 -1.0166 -0.2433 -0.9234 -0.4807C-0.8301 -0.7181 -0.556 -0.8567 -0.3076 -0.9226C-0.0591 -0.9884 0.3481 -1.0274 0.5674 -0.8756C0.7867 -0.7238 1.0132 -0.297 1.0083 -0.0115Z" />
        </svg>
        <span className="dl-icon">
          <DownloadIcon />
        </span>
      </a>

      <div className="bubble">
        <div className="bubble-inner">
          <span className="size-tag">
            {amount} <span className="size-unit">{unit}</span>
          </span>
          <span className="percent-tag">
            <span className="percent-dir">{direction}</span>
            <span className="percent-val">{shownPercent}</span>
            <span className="percent-char">%</span>
          </span>
        </div>
      </div>
    </div>
  );
}

export { BUBBLE_OUTLINE };

