async (page) => {
  const log = [];
  page.on('pageerror', e => log.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type()==='error') log.push('console: ' + m.text()); });
  await page.getByRole('button', { name: /Large photo/ }).click();
  await page.waitForTimeout(1500);
  // zoom in
  await page.getByRole('button', { name: 'Zoom in' }).click();
  await page.waitForTimeout(200);
  await page.getByRole('button', { name: 'Zoom out' }).click();
  await page.waitForTimeout(200);
  // toggles
  await page.getByRole('button', { name: 'Toggle smoothing' }).click();
  await page.getByRole('button', { name: 'Toggle background' }).click();
  await page.waitForTimeout(300);
  await page.screenshot({ path: '.playwright-mcp/mine-toggles.png' });
  // resize + palette toggles
  await page.getByLabel('Resize', { exact: true }).check();
  await page.waitForTimeout(300);
  await page.getByLabel('Reduce palette').check();
  await page.waitForTimeout(300);
  await page.screenshot({ path: '.playwright-mcp/mine-resize.png' });
  // back
  await page.getByRole('button', { name: 'Back' }).click();
  await page.waitForTimeout(600);
  const afterBack = page.url();
  return { log, afterBack, title: await page.title() };
}

