  await page.getByRole('button', { name: 'Save side settings' }).click();
  await page.waitForTimeout(300);
  await page.getByRole('button', { name: 'Back', exact: true }).click();
  await page.waitForTimeout(500);
  return { log, url: page.url() };
}

